'use strict';

// MODULES //

var floor = require( '@stdlib/math/base/special/floor' );
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var abs = require( '@stdlib/math/base/special/abs' );


// MAIN //

/**
* Creates conservative predicates for actual configured native widths.
* @private
* @param {PositiveInteger} lapackBytes - configured LAPACK integer bytes
* @param {PositiveInteger} blasBytes - configured BLAS integer bytes
* @throws {RangeError} invalid argument
* @returns {Function} native eligibility
*/
function configured( lapackBytes, blasBytes ) {
	var LMAX = ( (lapackBytes === 4) ) ? 2147483647 : 9007199254740991;
	var BMAX = ( (blasBytes === 4) ) ? 2147483647 : 9007199254740991;
	if ( ((((lapackBytes !== 4) && (lapackBytes !== 8))) || (((blasBytes !== 4) && (blasBytes !== 8)))) ) {
		throw new RangeError( 'invalid argument. Unsupported configured native integer widths.' );
	}
	/**
* Bounds actual selected Fortran control and terminal expressions.
* @private
* @param {NonNegativeInteger} count - helper count
* @param {integer} stride - helper stride
* @returns {boolean} eligibility
*/
	function trip( count, stride ) {
		if ( (count <= 1) ) {
			return true;
		}
		stride = abs( stride );
		if ( (((count > BMAX) || (stride === 0)) || (stride > BMAX)) ) {
			return false;
		}
		if ( (stride === 1) ) {
			return ((count < 5) || (count <= (BMAX-5)));
		}
		return ((count <= (BMAX-2)) && (stride <= floor((((BMAX-1))/((count+1))))));
	}
	/**
* Chooses fallback before native narrowing or mutation.
* @private
* @param {string|integer} uplo - selected triangle
* @param {NonNegativeInteger} N - matrix order
* @param {NonNegativeInteger} KD - bandwidth
* @param {Float64Array} AB - compact band storage
* @param {integer} r - band row stride
* @param {integer} c - band column stride
* @param {integer} o - band offset
* @returns {boolean} eligibility
*/
	function eligible( uplo, N, KD, AB, r, c, o ) {
		var dr;
		var dc;
		var k;
		var s;
		if ( ((((((N+1) > LMAX) || ((KD+1) > LMAX)) || (abs(r) > LMAX)) || (abs(c) > LMAX)) || (o > LMAX)) ) {
			return false;
		}
		if ( ((((KD !== 0) && (abs(r) > floor((LMAX/KD))))) || (((N > 1) && (abs(c) > floor((LMAX/((N-1)))))))) ) {
			return false;
		}
		dr = (KD*r);
		dc = (((N-1))*c);
		if ( (((o+max(dr, 0))+max(dc, 0)) > LMAX) ) {
			return false;
		}
		k = min( KD, (N-1) );
		if ( (k <= 1) ) {
			return true;
		}
		if ( (uplo === 121) ) {
			if ( ((((r < 0) && (c > (LMAX+r)))) || (((r > 0) && (c < (-LMAX+r))))) ) {
				return false;
			}
			s = (c-r);
		} else {
			s = r;
		}
		return ((abs(s) <= LMAX) && trip(k, s));
	}
	eligible.trip = trip;
	return eligible;
}


// EXPORTS //

module.exports = configured;
